    class WebPortal {
        - versionNumber: String
        - url: String
    }

    class Building {
        + id: String
        + name: String
        + energyClass: char
        + address: String
        + yearOfConstruction: int
        + owner: User
        - additionalEntries: List<AdditionalEntry>
        - images: List<Image>
        + addAdditionalEntry(entry: AdditionalEntry)
        + releaseEntry(entry: AdditionalEntry)
    }

    class User {
        + username: String
        + email: String
        + password: String
        + createBuilding()
        + manageEntries()
        + commentOnBuilding()
    }

    class Administrator {
        + idCardNumber: String
        } as Admin

    class AdditionalEntry {
        + name: String
        + isPublic: Boolean
        + type: String
        + value: String
    }

    class Image {
        + fileName: String
        + isProfilePhoto: Boolean
    }

    class Comment {
        + text: String
    }

    ' Relationships
    WebPortal "1" *-- "0..*" Building : provides catalog
    Building "1" *-- "0..*" User : owned by
    Building "1" *-- "0..*" AdditionalEntry : has entries
    Building "1" *-- "0..*" Image : has images
    User *-- "1" Comment : creates
}

package "Use Cases" {
    actor Visitor {
        usecase "UC1: Search Buildings" as searchBuildings
    }

    actor User {
        usecase "UC2: Register User" as registerUser
        usecase "UC3: Log In" as logIn
        usecase "UC4: Create Building" as createBuilding
        usecase "UC5: Add Entry" as addEntry
        usecase "UC6: Edit Entry" as editEntry
        usecase "UC7: Delete Entry" as deleteEntry
        usecase "UC8: Release Entry" as releaseEntry
        usecase "UC9: Comment on Building" as commentOnBuilding
    }

    actor Administrator {
        usecase "UC10: Set Up User Account" as setUpAccount
        usecase "UC11: Delete Comment" as deleteComment
    }

    ' Relationships between Use Cases
    User --> createBuilding
    User --> addEntry
    User --> editEntry
    User --> deleteEntry
    User --> releaseEntry
    User --> commentOnBuilding
    Administrator --> setUpAccount
    Administrator --> deleteComment
}

@enduml

