    endDate: Date
}

class Course {
    courseID: String
    name: String
    weeklyDuration: Integer
}

' Compositions
University o-- "*" Faculty
Faculty o-- "*" Institute
Faculty <|-- Employee

' Generalizations
Employee <|-- ResearchStaff
Employee <|-- AdministrativeStaff

' Aggregation from Institute to ResearchStaff
Institute o-- "*" ResearchStaff

' Aggregation from ResearchStaff to Project
Project ..> "*" ResearchStaff

' Association from Course to ResearchStaff with role
Course *-- ResearchStaff
ResearchStaff : "lecturer"

@enduml
